skills.card:
columnMath — Total, average, or find the smallest or largest value down one column of a table.
  needs: table: object, column: string, operation: string
  e.g. "add up the amount column" → {"table":{"headers":["name","amount"],"rows":[{"name":"Ana","amount":120},{"name":"Bo","amount":80}]},"column":"amount","operation":"sum"}

diffJson — Compare two JSON documents and list the paths added, removed and changed.
  needs: left: string, right: string
  e.g. "diff these two json documents" → {"left":"{\"name\":\"Ana\",\"age\":34}","right":"{\"name\":\"Bea\",\"age\":34,\"city\":\"Leeds\"}"}

filterRows — Drop the rows of a table that fail a condition.
  needs: table: object, column: string, operator: string, value: undefined
  e.g. "keep only rows where amount is over 100" → {"table":{"headers":["name","amount"],"rows":[{"name":"Ana","amount":120},{"name":"Bo","amount":80}]},"column":"amount","operator":">","value":100}

parseQueryString — Break a link’s ?key=value pairs apart and say what each holds.
  needs: query: string
  e.g. "parse this query string" → {"query":"?name=Ana&age=34"}

transposeTable — Pivot a table on its side, so rows become columns.
  needs: table: object
  e.g. "transpose this table" → {"table":{"headers":["name","q1","q2"],"rows":[{"name":"Ana","q1":1,"q2":2},{"name":"Bo","q1":3,"q2":4}]}}

loremIpsum — Generate meaningless placeholder filler to fill out a layout.
  optional: paragraphs: integer, sentencesPerParagraph: integer, seed: integer, startWithLorem: boolean
  e.g. "generate some placeholder text" → {}

rollDice — Roll dice in standard notation like 2d6+3, from a seed so the same roll can be repeated.
  needs: notation: string, seed: integer
  e.g. "roll 2d6 with seed 7" → {"notation":"2d6","seed":7}

